import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse(`{"title":"Install options","description":"What Wake's installer needs, its options, how to serve Wake on a domain, what the installer writes, and its hardened services.","frontmatter":{"description":"What Wake's installer needs, its options, how to serve Wake on a domain, what the installer writes, and its hardened services."},"headers":[],"relativePath":"run/install-options.md","filePath":"run/install-options.md","lastUpdated":1794486787000}`),n={name:"run/install-options.md"};function i(d,e,r,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="install-options" tabindex="-1">Install options <a class="header-anchor" href="#install-options" aria-label="Permalink to &quot;Install options&quot;">​</a></h1><p><a href="/wake-dist/docs/start/install">Install Wake</a> installs the whole stack on one Linux, macOS or Windows (WSL 2) machine with one command. This page covers what it needs, its options, serving Wake on a domain and what it writes.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux, macOS, or Windows with WSL 2 (<a href="/wake-dist/docs/start/install#windows-with-wsl-2">inside a distribution</a>), with Docker Engine or Docker Desktop running, and the Docker Compose v2 plugin (<code>docker compose version</code>).</li><li><code>curl</code>, and <code>sha256sum</code> or <code>shasum</code>.</li><li><code>ssh-keygen</code> from OpenSSH 8.1 or newer, which verifies the release signature: macOS ships it; on Linux it is the <code>openssh-client</code> package. Without it the installer, <code>wake-server upgrade</code> and <code>wake-server install-cli</code> stop with one line naming the package.</li><li>For a domain: a machine reachable from the internet on ports 80 and 443.</li></ul><p>Before it writes anything, the installer checks the tools, the directory and the ports, and stops with one line naming what is missing. A domain&#39;s DNS and firewall can only be checked once Wake runs: see <a href="#install-on-a-domain">Install on a domain</a>. The images are public: no GitHub account, <code>gh</code> or <code>docker login</code> is needed.</p><p>Every release is signed. The installer, <code>wake-server</code> and <code>wake upgrade</code> use a downloaded file only when the release&#39;s signature verifies with the key they carry and the file matches the release&#39;s checksums. To check the installer itself before running it, see <a href="/wake-dist/docs/reference/verify-installer">Verify a download</a>.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>Options go after <code>sh -s --</code> when you pipe the script, or after <code>sh install.sh</code>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--dir DIR</code></td><td><code>$HOME/wake-server</code></td><td>Installation directory. For a new installation it must be empty or missing; running again on an existing one is safe (see <a href="#run-it-again">Run it again</a>)</td></tr><tr><td><code>--port PORT</code></td><td><code>8080</code></td><td>Local mode: the app&#39;s port on <code>127.0.0.1</code></td></tr><tr><td><code>--s3-port PORT</code></td><td><code>8081</code></td><td>Local mode: evidence storage&#39;s port on <code>127.0.0.1</code></td></tr><tr><td><code>--domain HOST</code></td><td></td><td>Serve <code>https://HOST</code> instead (see <a href="#install-on-a-domain">Install on a domain</a>)</td></tr><tr><td><code>--no-auto-upgrade</code></td><td></td><td>Leave daily upgrades off (later: <code>wake-server auto-upgrade on</code>)</td></tr><tr><td><code>--no-cli</code></td><td></td><td>Do not install the <code>wake</code> CLI (later: <code>wake-server install-cli</code>)</td></tr><tr><td><code>--no-browser</code></td><td></td><td>Do not open the browser at the end</td></tr><tr><td><code>--cli-only</code></td><td></td><td>Install only the <code>wake</code> CLI of the release, on a machine that does not run the server: see <a href="/wake-dist/docs/start/cli#install-the-cli">Install the CLI</a>. Takes no other option</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td></td><td>Show the options</td></tr></tbody></table><p>For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/wake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --s3-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8301</span></span></code></pre></div><p>A busy port stops the installer with a line naming the port and the option to change it. An invalid option exits <code>2</code> and writes nothing.</p><p>In local mode Wake listens on <code>127.0.0.1</code> only. The app, the API, OAuth and MCP share one address, <code>http://localhost:&lt;port&gt;</code> (<code>8080</code> unless you passed <code>--port</code>), and evidence files go to <code>http://localhost:&lt;s3-port&gt;</code> (<code>8081</code> unless you passed <code>--s3-port</code>).</p><h2 id="what-else-the-installer-sets-up" tabindex="-1">What else the installer sets up <a class="header-anchor" href="#what-else-the-installer-sets-up" aria-label="Permalink to &quot;What else the installer sets up&quot;">​</a></h2><p>Once the stack is healthy, the installer:</p><ul><li><strong>Turns on daily upgrades</strong>, as <code>wake-server auto-upgrade on</code> does (see <a href="/wake-dist/docs/run/upgrade#upgrade-on-a-schedule">Upgrade on a schedule</a>), unless <code>--no-auto-upgrade</code> is given. Without <code>crontab</code> it prints a <code>!</code> line and goes on.</li><li><strong>Puts <code>wake-server</code> on your <code>PATH</code></strong>: a small script in <code>$HOME/.local/bin</code> (<code>WAKE_BIN_DIR</code> changes the directory) that runs the installation&#39;s <code>wake-server</code>, marked <code># Managed by the Wake installer</code>. It never replaces a file there that is not its own. When that directory is not on <code>PATH</code>, the output gives the <code>export PATH=...</code> line to add to your shell profile.</li><li><strong>Installs the <code>wake</code> CLI</strong> of the same release when Node.js 24 or newer and npm are present: it downloads <code>wake-cli.tgz</code>, verifies it like the other files and runs <code>npm install --global</code> on it. Without Node it says so; install Node, then run <code>wake-server install-cli</code>. A file that does not verify is not installed. When npm fails, the output shows npm&#39;s last lines and the command to retry.</li><li><strong>Opens the browser</strong> on the sign-up page with <code>open</code> (macOS) or <code>xdg-open</code> (Linux, with a display); <code>WAKE_OPEN_COMMAND</code> names another program, and <code>--no-browser</code> skips it. Without one, the output names the address to open.</li><li><strong>Records the installation for the CLI</strong> in <code>~/.config/wake/server.json</code> (or under <code>XDG_CONFIG_HOME</code>): its address and directory, so <code>wake setup</code> finds it.</li></ul><p>A step it could not do shows <code>!</code> with the reason and the command that does it later; the install still exits <code>0</code>. The installer never touches a repository.</p><p>One machine keeps one Wake server: when another installation exists in another directory, the installer exits <code>1</code> and names it. Run the installer with <code>--dir</code> set to that directory, or remove that installation first.</p><h2 id="install-on-a-domain" tabindex="-1">Install on a domain <a class="header-anchor" href="#install-on-a-domain" aria-label="Permalink to &quot;Install on a domain&quot;">​</a></h2><p>To serve Wake on <code>https://wake.example.com</code> with a certificate:</p><ol><li><p>Create DNS records (<code>A</code>, and <code>AAAA</code> for IPv6) for both <code>wake.example.com</code> and <code>s3.wake.example.com</code>, pointing at the machine. Evidence storage needs its own name: the presigned upload and download addresses sign the host.</p></li><li><p>Open ports 80 and 443 in the firewall, and keep them free: Caddy listens on both, and obtains and renews the certificates for both names through them.</p></li><li><p>Run the installer with the domain:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --domain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake.example.com</span></span></code></pre></div></li></ol><p>The server then uses <code>https://wake.example.com</code> as its address, with secure cookies, and evidence addresses start with <code>https://s3.wake.example.com/</code>. Every response of the app&#39;s address carries <code>Strict-Transport-Security: max-age=31536000</code>, so browsers then use only HTTPS for it; local mode serves plain HTTP and never sends it.</p><h3 id="your-first-account" tabindex="-1">Your first account <a class="header-anchor" href="#your-first-account" aria-label="Permalink to &quot;Your first account&quot;">​</a></h3><p>An address on the internet can be reached by anyone, so a domain install closes sign-up: it writes <code>SIGN_UP=invitation</code> and a random <code>SETUP_TOKEN</code> to <code>.env</code>, and prints a sign-up link that carries the token once, at the end:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  → Open https://wake.example.com/sign-up?setup=&lt;token&gt; and create your account there.</span></span>
<span class="line"><span>    This link creates the first account and works only until that account exists.</span></span></code></pre></div><p>Open it and create your account before anything else. Until you do, a sign-up without the token is refused, and so is a first account through a sign-in provider: link providers to your account afterwards. Then <a href="/wake-dist/docs/use/workspaces#invite-people">invite</a> the people who should join. Lost the link? The token is the <code>SETUP_TOKEN</code> line of the installation&#39;s <code>.env</code>. See <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a>.</p><p>A local install writes neither line: it listens only on this machine, so its sign-up stays open. An installation made by an older installer keeps its sign-up as it was; to close it, see <a href="/wake-dist/docs/run/sign-up#only-by-invitation">Only by invitation</a>.</p><p><code>--domain</code> takes a DNS name without a scheme or port (<code>http://wake.example.com</code> and <code>localhost:8080</code> exit <code>2</code>), and cannot be combined with <code>--port</code> or <code>--s3-port</code>.</p><p>When the names do not resolve yet, the installer waits 120 seconds for <code>https://wake.example.com/health</code>, then exits <code>1</code> with a line naming DNS and ports 80 and 443. The stack keeps running and Caddy keeps trying to obtain the certificates: once DNS is right, <code>curl -f https://wake.example.com/health</code> answers, and <code>wake-server status</code> shows each service&#39;s health meanwhile.</p><h2 id="what-the-installer-writes" tabindex="-1">What the installer writes <a class="header-anchor" href="#what-the-installer-writes" aria-label="Permalink to &quot;What the installer writes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In the directory</th><th>Contents</th></tr></thead><tbody><tr><td><code>.env</code></td><td>The installation&#39;s settings and its generated secrets (the Postgres password, the storage&#39;s keys: random 256-bit values; on a domain, also <code>SIGN_UP=invitation</code> and the <code>SETUP_TOKEN</code> of the first account&#39;s link). Mode <code>0600</code>; nothing prints them but the domain install&#39;s sign-up link. Keep a copy somewhere safe</td></tr><tr><td><code>compose.yaml</code></td><td>Postgres, MinIO, the server, the web app and Caddy; only Caddy publishes ports</td></tr><tr><td><code>Caddyfile</code></td><td>The front door: the server&#39;s paths (<code>/v1/</code>, <code>/mcp</code>, <code>/oauth/</code>, <code>/.well-known/</code>, <code>/health</code>) go to the server, everything else to the web app; the storage address serves only the evidence bucket</td></tr><tr><td><code>wake-server</code></td><td>The manager: see <a href="/wake-dist/docs/reference/wake-server">wake-server</a></td></tr><tr><td><code>LICENSE</code></td><td>The terms the installed release ships under, the <a href="/wake-dist/docs/reference/license">Wake Free License</a>, verified like the other files</td></tr><tr><td><code>backups/</code></td><td>Backups of the database, the evidence files and <code>.env</code>, created by the first backup, upgrade or restore</td></tr></tbody></table><p>Do not edit <code>compose.yaml</code>, <code>Caddyfile</code>, <code>LICENSE</code> or <code>wake-server</code>: an upgrade replaces them with the new release&#39;s copies. Your own settings go in <code>.env</code>, which upgrades keep; see <a href="/wake-dist/docs/reference/environment#installation-settings">Server environment</a>.</p><p>Each directory is its own Docker Compose project, so two installations never share containers or volumes. To run Docker Compose commands on it yourself, run them in the directory, for example <code>cd &lt;your installation directory&gt;</code> and then <code>docker compose logs server</code>.</p><p>Run <code>wake-server</code> as the user who installed Wake, never with <code>sudo</code>: the directory is readable only by that user (mode <code>0700</code>), and the daily upgrade lives in that user&#39;s crontab.</p><p>When the images cannot be pulled or the stack does not become healthy, the installer removes what it started and wrote; only a stack that is healthy but not yet reachable at its address keeps running, as above.</p><h2 id="run-it-again" tabindex="-1">Run it again <a class="header-anchor" href="#run-it-again" aria-label="Permalink to &quot;Run it again&quot;">​</a></h2><p>Running the installer on a directory that already holds an installation changes nothing in it (no file, container, secret or daily-upgrade setting) and prints <code>Wake &lt;version&gt; is already installed in &lt;dir&gt;; nothing in it changes.</code> It adds the <code>wake-server</code> command and the CLI when they are missing, and names <code>wake-server upgrade</code> when its release is newer. <code>--port</code>, <code>--s3-port</code> and <code>--domain</code> apply only to a new installation.</p><h2 id="hardened-services" tabindex="-1">Hardened services <a class="header-anchor" href="#hardened-services" aria-label="Permalink to &quot;Hardened services&quot;">​</a></h2><p>The server and the web app run with a read-only root file system, no capabilities and <code>no-new-privileges</code>, as users other than root. The server reaches evidence storage as its own storage user, <code>wake-server</code>, which can only read, write, list and delete the objects of the <code>wake-evidence</code> bucket, never with the storage&#39;s root keys. Every service keeps its Docker logs in at most five files of 10 MB, so one installation&#39;s container logs stay under about 300 MB; see <a href="/wake-dist/docs/run/logs">Logs</a>.</p>`,39)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
